\label{thm_intro:bounded_bisector}
    An orbit $\mathcal{O}_F$ has the proper-on-bisector property if and only if :
    \begin{equation}
    \operatorname{Cone}(F^\vee \cup w_0\cdot F^\vee) =\mathfrak{a}^* ,\end{equation} 
    Here $\operatorname{Cone}(S)$ denotes the smallest convex cone in $\mathfrak{a}^\ast$ containing the set $S$, and $w_0$ is the longest word of the Weyl group.

     The special orbit $\mathcal{O}_{F_\rho}$ has the proper-on-bisector property if and only if :
     $$w_0\cdot \operatorname{Span}_0(F_\rho)\cap \operatorname{Span}_0(F_\rho)=\lbrace 0\rbrace.$$ 
Here $\operatorname{Span}_0(F_\rho)$ is the linear part of the smallest affine subspace containing $F_\rho$. 
In particular if $F_\rho$ is a vertex, then $\mathcal{O}_{F_\rho}$ has the proper-on-bisector property.

\label{thm_intro:PorperBissectrors consequences}
    Let $(C_p^{\Pi})_{p\in \Pi}$ be the ideal Poisson--Voronoi tessellation associated with a polyhedral Finsler metric on a symmetric space $\mathbb{X}$. We have the following dichotomy: 
    \begin{enumerate}
        \item 
    If $\mathcal{O}_{F_\rho}$ has the proper-on-bisector property, then almost surely the intersection of two cells is bounded. 

    \item If $\mathcal{O}_{F_\rho}$ does not have the proper-on-bisector property, then almost surely the intersection of two cells is unbounded. 
    \end{enumerate}

The ideal Selberg--Poisson--Voronoi tessellation satisfies the following properties: 
   \begin{enumerate}
     \item Almost surely, the side between any two cells is bounded. 

     \item Almost surely, each cell $c$ is convex, has locally finitely many sides and its closure meets $\partial \mathcal{X}$ in a single point $P_c$. 

     \item Moreover, for every projective line $L$  passing through $P_c$ and some  $X\in \mathcal{X}$, the intersection of $L$ with the cell $c$ contains a non-trivial segment $[X',P_c)$.
   \end{enumerate}

\label{prop:Tits angle}
Let $f\in \mathcal{F}_{\Theta_1}$ and $f^\text{opp}\in \mathcal{F}_{\iota(\Theta_1)}$ be a transverse pair of flags. Let $g\in \mathcal{F}_{\Theta_2}$. The relative positions $w_1$, $w_2$ corresponding to the pairs $(f,g)$ and $(f^\text{opp},g)$ satisfy:

$$ [w_0w_1]\leq [w_2]. $$

\label{lem: Alternative definition Fvee}
Alternatively for any $v \in F$, we can write \begin{equation}\label{eqn: def of Fvee bis}
        \overline{F^\vee} \coloneqq \{ \beta \in (B^N)^* : \beta(v)=1 \} 
    \end{equation} 

Equivalently, $\overline{F^\vee}$ is exactly the convex hull of the linear forms $\omega\in \operatorname{vert}((B^N)^*))$ such that $\omega=1$ on $F$.

\label{prop:Formula horofunction standard}
The standard horofunction is independent of the choice of $f\in F$ and is also given by:
\begin{equation}
    \label{eq:Formula standard horofunctions}
        h_F(x) = \sup_{\beta\in F^\vee} -\beta(x)=\max_{\omega\in \operatorname{vert}(\overline{F^\vee})} -\omega(x)
\end{equation}

\label{prop:comparing RF and SF to Gflip and Gfix}
    The subgroups $R_F\subset S_F$ contain $G^{\operatorname{flipped}}_F$ and the intersection of the maximal compact $K$ with $P_{\Delta\setminus \Theta^{\operatorname{stable}}_F}$. 
    The intersection of $R_F$ and $S_F$ with $G_F^{\operatorname{fixed}}$ is exactly the maximal compact of $G_F^{\operatorname{fixed}}$.

\label{prop:Lie algebra of stabilizer}
$${\operatorname{Lie}}(R_F)={\operatorname{Span}_0}(F)\oplus \mathfrak{m} \oplus \bigoplus_{\alpha \in \Sigma^+ \setminus {\operatorname{Span}}(\Theta_F^{\operatorname{stable}})}\mathfrak{g}_\alpha \bigoplus_{\alpha \in {\operatorname{Span}}(\Theta_F^{\operatorname{fixed}})}\mathfrak{k}_\alpha\bigoplus_{\alpha \in {\operatorname{Span}}(\Theta_F^{\operatorname{flipped}})}\mathfrak{g}_{\alpha}\oplus\mathfrak{g}_{-\alpha},$$
$${\operatorname{Lie}}(S_F)={\operatorname{Span}}(F)\oplus \mathfrak{m} \oplus \bigoplus_{\alpha \in  \Sigma^+ \setminus {\operatorname{Span}}(\Theta_F^{\operatorname{stable}})}\mathfrak{g}_\alpha  \bigoplus_{\alpha \in {\operatorname{Span}}(\Theta_F^{\operatorname{fixed}})}\mathfrak{k}_\alpha\bigoplus_{\alpha \in {\operatorname{Span}}(\Theta_F^{\operatorname{flipped}})}\mathfrak{g}_{\alpha}\oplus \mathfrak{g}_{-\alpha}.$$

\label{prop:Explicit formula for Horofunctions}
    Let $o\in \mathbb{X}$ be a point fixed by $K_\Theta$. Let $h_F\in \mathcal{O}_F$ be the model horofunction on $\mathbb{X}$, associated to the standard horofunction $h_F$ on $\mathfrak{a}$ via the embedding $\partial ^N\mathfrak{a}\subset \partial^N \mathbb{X}$, and with $h(o)=0$. We have the following:
\begin{equation}\label{eq:Formula horofunction in symmetric space}
h(x)=\max_{i\in I_F,\, p\in E^F_i}\lVert \omega_i\rVert b_{p,o}(x).\end{equation}

\label{prop: proper bisectors}
    The orbit $\mathcal{O}_F$ has the proper-on-bisector property if and only if:
    \begin{equation}\label{eq:Convex combination}
    \operatorname{Cone}(F^\vee \cup w_0\cdot F^\vee) =\mathfrak{a}^* ,\end{equation} 
    where $\operatorname{Cone}(S)$ denotes the smallest convex cone in $\mathfrak{a}^\ast$ containing $S$.

\label{prop:Caracterisation proper bisectors Frho}
The orbit $\mathcal{O}_{F_\rho}$ has the proper-on-bisector property if and only if: $$w_0\cdot \operatorname{Span}_0(F_\rho)\cap \operatorname{Span}_0(F_\rho)=\lbrace 0\rbrace.$$ 
In particular if $F_\rho$ is a vertex, $\mathcal{O}_{F_\rho}$ has the proper-on-bisector property.

\label{cor: proper bisectors when opposition involution is trivial}
    If the opposition involution is trivial, then the orbit $\mathcal{O}_{F_\rho}$ has the proper-on-bisector property if and only if 
    $F_\rho$ is a vertex.

\label{prop:ProperbissectorLinear forms}
Let $\omega$ be a dominant linear form on $\mathfrak{a}$ and let $\Theta\subset \Delta$ be the set of indices $i$ such that 
$\omega(\tau_i) =\min_{j\in \Delta}\omega(\tau_j)$. The face $F_\rho$ for the metric $N_\omega$ has the proper-on-bisector property if and only if $\#(\Theta\cap \iota(\Theta))\leq 1$.

\label{prop: rho in terms of fundamental weights}
    The restricted Weyl vector $\rho$, see (\ref{eqn: weyl vector}), satisfies 
        \[ \rho = \sum_{\alpha \in \Delta} (m_\alpha + 2 m_{2\alpha}) \varpi_\alpha \]

If $\alpha$ is simple then the reflection $s_\alpha$ negates $\alpha$ and permutes the other positive roots. 
    Hence $s_\alpha(\rho)=\rho-m_\alpha\alpha-m_{2 \alpha}2 \alpha$ and 
    \begin{align*}
        \rho(\widehat{\alpha}) & = (s_\alpha \rho)(s_\alpha \widehat{\alpha}) = (\rho-m_\alpha\alpha-m_{2\alpha}2\alpha)(-\widehat{\alpha}) \\
        & = - \rho(\widehat{\alpha}) + m_\alpha\alpha(\widehat{\alpha}) + m_{2\alpha}2\alpha(\widehat{\alpha}) = - \rho(\widehat{\alpha}) + 2 m_\alpha + 4 m_{2 \alpha} 
    \end{align*}
     implies $\rho(\widehat{\alpha})=m_\alpha+2m_{2\alpha}>0$.

\label{defn:cylinders}
For a base-point $o\in \mathbb{X}$ and $r, R\in [-\infty, +\infty]$ the \emph{cylinder centered at $o$} is given by:
$$C^o_{r,R}=\left\lbrace f \in \overline{\mathcal{D}^N(\mathbb{X})}\mid r\leq f(o)\leq R\right \rbrace.$$

