Since $\rho$ belongs to the interior of $F_\rho^\vee$, if we take any ray $\mathbb{R}_{\ge 0} v\subset C_\rho$, then $\rho(v)\leq 0$ with equality if and only if $\beta(v)=0$ for all $\beta\in F_\rho^\vee$, i.e.\  if and only if $v \in \operatorname{Span}_0(F_\rho)$. If moreover $v\in \operatorname{Span}_0(F_\rho)^\perp$, then $\rho(v)<0$. This implies that there is some $A>0$ such that for all $\lambda \ge 0$, $ \rho(\lambda v)\leq- A N(\lambda v)$. These constants $A$ can be chosen uniformly as the set of rays in $C_\rho\cap \operatorname{Span}_0(F_\rho)^\perp$ is compact.

 \medskip

The second point is a direct consequence of the first one: the diameter of the intersection of level sets of $\rho$ and $C_\rho$ grows at most linearly in $t$.

\label{prop:Existence Limiting measure}
    The family of measures $\mu_t = \frac1{m_t}(\iota_t)_*\operatorname{Leb}$ converges as $t \to \infty$ up to subsequence to a $\sigma$-finite measure $\mu_N$ supported on the space of horofunctions $\mathcal{H}^N(\mathbb{X})$. 
    Every such limit is $G$-invariant.

\label{remark: vF vs f0}
    Note that for any $f_0 \in F$, the class $[v-s v_F] = [v-sf_0]$, so $\pi$ can equivalently be defined with $f_0$ in place of $v_F$. 
    This shows that still $\Psi_F$ continuously extends $\Psi$  if $v_F$ replaces $f_0$ in its definition.

\label{prop: Existence measure}
    The space of horofunctions of a given type $\mathcal{O}_F\simeq G/R_F$ admits a $G$-invariant measure if and only if the following linear form on $\mathfrak{a}$ vanishes on $\operatorname{Span}_0(F)$:
    \begin{equation}\label{eqn: form on aff(F)}
        \sum_{\alpha \in \Sigma^+ \setminus \text{Span}(\Theta_F^\text{flip})} m_{\alpha}\alpha.    
    \end{equation}

\label{prop:Identification Selberg and Finler}
    The natural identification $\mathbb{X}\simeq \mathcal{X}$ extends to a $G$-equivariant homeomorphism $\phi: \overline{\mathcal{D}^{N_{\iota\omega_1}}(\mathbb{X})}\to S^2{V^*}^{\geq 0}$ such that:
\begin{itemize}
\item[(i)] For all $X\in \mathbb{X}\simeq \mathcal{X}$, for all $h\in \overline{\mathcal{D}^{N_{\iota\omega_1}}(\mathbb{X})}$ :
$$h(X)-\frac{1}{2}\log(n)\leq \mathfrak{s}(X,\phi(h))\leq h(X),$$
\item[(ii)] $\phi$ is equivariant with respect to the $\mathbb{R}$-action defined by $\lambda\cdot h=(X \mapsto h(X)+\lambda)$ and $\lambda \cdot Y=e^{2\lambda} Y$ for $\lambda\in \mathbb{R}$, $h\in \overline{\mathcal{D}^N(\mathbb{X})}$ and $Y\in S^2V^{\geq 0}$.
\item[(iii)]  This homeomorphism identifies $\mathcal{O}_{F_k}\subset \overline{\mathcal{D}^{N_{\iota\omega_1}}(\mathbb{X})}$ with $\mathcal{O}_k\subset S^2{V^*}^{\geq 0}$.
\end{itemize}

\label{lem:Proper Horofunctions Selberg}
    Let $Y_1,Y_2\in \mathcal{O}_1$ be in generic position, meaning that the lines $\ker Y_1$ and $\ker Y_2$ are distinct. Then for any $O\in \mathcal{X}^*$, there exist $A,B>0$ such that for all $X\in \mathcal{X}$ such that $\mathfrak{s}(X,Y_1)=\mathfrak{s}(X,Y_2)$:
    $$\mathfrak{s}(X,Y_1)\geq A\mathfrak{s}(X,O)-B. $$

\label{thm:Selberg Main}
    Let $\Pi_0$ be a Poisson point process on $\mathcal{O}_{F_{1}}$ with intensity $\mu_{1}$, and let $(\mathcal{C}_Y)_{Y\in \Pi_0}$ be the corresponding Voronoi tessellation of $\mathcal{X}$. Almost surely the following holds:

    \begin{itemize}
        \item[(i)] For every $Y_0\in \Pi_0$ the cell $\mathcal{C}_{Y_0}$ is projectively convex, has locally finitely many sides and its closure contains a single point $P_{Y_0}\in\partial \mathcal{X}$, which is the unique point on which the linear form on $S^2V$ associated to $Y_0$ vanishes.
        \item[(ii)] For every distinct $Y_1,Y_2\in \Pi_0$ the side $\mathcal{C}_{Y_1}\cap\mathcal{C}_{Y_2}\subset \mathcal{X}$ is bounded.
        \item[(iii)] For every projective line $L$ in $\mathbb{P}(S^2V)$ passing through $P_{Y_0}$ and some $[X]$ for $X\in \mathcal{X}$, the intersection of $L$ with $\mathcal{C}_{Y_0}$ contains a non-trivial segment $[X',P_{Y_0})$.
    \end{itemize}
